function extractCosmetic(rows) {
  const findAfter = (field, heading, stop) => {
    const index = rows.findIndex(row => row[field] === heading);
    if (index < 0) throw new Error('Missing sheet heading: ' + heading);
    for (const row of rows.slice(index + 1)) {
      const value = row[field];
      if (stop.includes(value)) break;
      if (value !== undefined && value !== null && String(value).trim()) return value;
    }
    throw new Error('No value below sheet heading: ' + heading);
  };
  const artist = String(findAfter('Type to search:', 'Creator', ['Discord alias(es)']));
  const name = String(findAfter('col_2', 'Title/notes', ['Twitch ID', 'Add aliases and IDs to the UserLookup tab'])).split('\n')[0];
  const selection = rows.find(row => row.col_3 === 'Select row to get info:');
  const rowNumber = selection?.col_5;
  if (!name.trim() || !artist.trim() || !Number.isSafeInteger(Number(rowNumber)) || Number(rowNumber) <= 0) {
    throw new Error('Incomplete next cosmetic selection; existing files were preserved');
  }
  return { CosmeticName: name, CosmeticRow: rowNumber, Artist: artist };
}
return [{json:extractCosmetic($input.all().map(item=>item.json))}];

